package org.dextur.reputation.application;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;
import org.dextur.reputation.api.*;
import org.dextur.reputation.domain.policy.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
class PolicyConfigurationTest {
    @org.junit.jupiter.api.io.TempDir Path directory;
    PolicyEngine.Input input(long score,String tier){return new PolicyEngine.Input(new ReputationSnapshot(UUID.randomUUID(),"global",score,0,score,tier,1,Instant.EPOCH,Instant.EPOCH),null,RecoverySnapshot.Status.AVAILABLE,0);}
    @Test void boundariesLimitsAndMultipliers()throws Exception{var rules=PolicyConfiguration.load(directory);assertFalse(rules.healthEnabled());assertTrue(rules.policies().keySet().containsAll(PolicyRules.BUILT_INS));for(long score:new long[]{-251,-250,-100,-99,99,100,249,250}){var input=input(score,"NEUTRAL");long expected=score<=-250?1:score<=-100?3:score>=250?15:score>=100?10:7;assertEquals(expected,PolicyEngine.evaluate(input,rules,"auction.listing-limit",Map.of(),Instant.EPOCH,false).limit());double multiplier=score<=-100?3:score<=-25?1.5:score>=250?0.9:1;assertEquals(multiplier,PolicyEngine.evaluate(input,rules,"chat.cooldown",Map.of(),Instant.EPOCH,false).multiplier().doubleValue());}assertEquals(ReputationPolicyResult.Decision.UNAVAILABLE,PolicyEngine.evaluate(input(0,"NEUTRAL"),rules,"unknown.policy",Map.of(),Instant.EPOCH,false).decision());}
    @Test void recoveryTierContextAndPriorityAreDeterministic()throws Exception{Files.writeString(directory.resolve("features.yml"),"config-version: 1\npolicies:\n  test.policy:\n    enabled: true\n    names: {ru_RU: Тест, en_US: Test}\n    rules:\n      - {priority: 20, when: {reputation-at-least: 10}, decision: LIMITED, limit: 5}\n      - {priority: 10, when: {tiers: [HONORED], recovery: [ACTIVE], context: {mode: verified}}, decision: DENY}\n      - {priority: 100, decision: ALLOW}\n");var rules=PolicyConfiguration.load(directory);var basic=input(100,"HONORED");var active=new PolicyEngine.Input(basic.profile(),null,RecoverySnapshot.Status.ACTIVE,5);assertEquals(ReputationPolicyResult.Decision.DENY,PolicyEngine.evaluate(active,rules,"test.policy",Map.of("mode","verified"),Instant.EPOCH,false).decision());assertEquals(5,PolicyEngine.evaluate(active,rules,"test.policy",Map.of(),Instant.EPOCH,false).limit());assertThrows(UnsupportedOperationException.class,()->rules.policies().clear());}
    @Test void rejectsAmbiguityBoundsAndEmergencyRestrictions()throws Exception{var defaults=new String(getClass().getResourceAsStream("/features.yml").readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);for(String broken:List.of(defaults.replace("priority: 20","priority: 10"),defaults.replace("maximum-single-adjustment: 10000","maximum-single-adjustment: 9223372036854775807"),defaults.replace("value: 16","value: 0"),defaults.replace("support.emergency-contact:\n    enabled: true","support.emergency-contact:\n    enabled: false"))){Files.writeString(directory.resolve("features.yml"),broken);assertThrows(Exception.class,()->PolicyConfiguration.load(directory));}}
    @Test void additiveFallbackPreservesCustomFileAndLocales()throws Exception{Path file=directory.resolve("features.yml");String custom="config-version: 1\nhealth: {enabled: true}\n";Files.writeString(file,custom);var rules=PolicyConfiguration.load(directory);assertTrue(rules.healthEnabled());assertEquals(custom,Files.readString(file));var ru=Messages.bundled(org.dextur.reputation.domain.PlayerLanguage.ru_RU);var en=Messages.bundled(org.dextur.reputation.domain.PlayerLanguage.en_US);var expected=YamlFiles.resource("/lang/ru_RU.yml");assertEquals(expected.keySet(),YamlFiles.resource("/lang/en_US.yml").keySet());for(String key:expected.keySet())if(key.startsWith("policy-")||key.startsWith("admin-")){var values=new HashMap<String,String>();for(String name:Messages.placeholders((String)expected.get(key)))values.put(name,"literal <red>value</red>");assertNotNull(ru.content(org.dextur.reputation.domain.PlayerLanguage.ru_RU,key,values));assertNotNull(en.content(org.dextur.reputation.domain.PlayerLanguage.en_US,key,values));}}
    @Test void administrativeArgumentsAreSubstitutedLiterallyInBothLocales()throws Exception{for(var locale:org.dextur.reputation.domain.PlayerLanguage.values()){var messages=Messages.bundled(locale);var result=messages.render(locale,"admin-applied",Map.of("operation","operation-123","player","<red>Player</red>","value","-100","admin","-150"));String plain=net.kyori.adventure.text.serializer.plain.PlainTextComponentSerializer.plainText().serialize(result);assertTrue(plain.contains("operation-123")&&plain.contains("<red>Player</red>")&&plain.contains("-100")&&plain.contains("-150"));assertFalse(plain.contains("{player}"));}}
}
